using System.Security.Cryptography.X509Certificates;
using System.Text.Json.Nodes;
using DotNet.Testcontainers.Builders;
using DotNet.Testcontainers.Containers;

namespace Keel.IntegrationTests.Idp;

/// <summary>
/// A real Keycloak (the image the product ships with) in a throwaway container on ephemeral ports, with the shipped dev realm, TLS with
/// client-certificate authentication, a truststore holding ONLY the test CA, a CRL from that CA, and then the opt-in CAC/PIV overlay of
/// this repository applied by its own script (ADR-0058). The PKI is generated by scripts/idp/generate-test-pki.sh and is DEV/TEST ONLY.
/// Never touches the dev stack or its ports.
/// </summary>
public abstract class KeycloakCacFixture : IAsyncLifetime
{
    internal const string AdminPassword = "keel-test-kc-admin";
    private readonly string _work = Path.Combine(Path.GetTempPath(), "keel-cac-" + Guid.NewGuid().ToString("N")[..8]);
    private IContainer? _keycloak;

    /// <summary>CAC_FALLBACK given to the overlay script: none or password.</summary>
    protected abstract string Fallback { get; }

    internal string PkiDir => Path.Combine(_work, "pki");
    internal string Origin { get; private set; } = "";
    internal X509Certificate2 Ca { get; private set; } = null!;

    public async ValueTask InitializeAsync()
    {
        var repo = FindRepoRoot();
        Directory.CreateDirectory(_work);
        await RunAsync("bash", [Path.Combine(repo, "scripts/idp/generate-test-pki.sh"), PkiDir]);
        Ca = X509CertificateLoader.LoadCertificateFromFile(Path.Combine(PkiDir, "ca.crt"));

        // What Keycloak may read: the server key pair, the CA (truststore) and the CRL. Client keys never leave the host.
        var staged = Path.Combine(_work, "server");
        Directory.CreateDirectory(staged);
        foreach (var f in new[] { "server.crt", "server.key", "ca.crt" })
        {
            var target = Path.Combine(staged, f);
            File.Copy(Path.Combine(PkiDir, f), target);
            Readable(target);
        }
        var crl = Path.Combine(_work, "crl.pem");
        File.Copy(Path.Combine(PkiDir, "crl.pem"), crl);
        Readable(crl);

        // The shipped dev realm with this run's redirect URI for the scripted browser.
        var realm = JsonNode.Parse(await File.ReadAllTextAsync(Path.Combine(repo, "deploy/compose/keycloak/keel-realm.json")))!;
        var client = realm["clients"]!.AsArray().Single(c => c!["clientId"]!.GetValue<string>() == "keel-web")!;
        client["redirectUris"] = new JsonArray(IdpBrowser.RedirectUri);
        client["webOrigins"] = new JsonArray("http://localhost:59999");
        var realmFile = Path.Combine(_work, "keel-realm.json");
        await File.WriteAllTextAsync(realmFile, realm.ToJsonString());

        _keycloak = new ContainerBuilder("quay.io/keycloak/keycloak:26.4")
            .WithCommand("start-dev", "--import-realm", "--https-port=8443",
                "--https-certificate-file=/pki/server.crt", "--https-certificate-key-file=/pki/server.key",
                "--https-client-auth=request", "--truststore-paths=/pki/ca.crt")
            .WithEnvironment("KC_BOOTSTRAP_ADMIN_USERNAME", "admin")
            .WithEnvironment("KC_BOOTSTRAP_ADMIN_PASSWORD", AdminPassword)
            .WithEnvironment("KC_HEALTH_ENABLED", "true")
            .WithResourceMapping(new DirectoryInfo(staged), "/pki")
            .WithResourceMapping(new FileInfo(crl), "/opt/keycloak/conf/")
            .WithResourceMapping(new FileInfo(realmFile), "/opt/keycloak/data/import/")
            .WithResourceMapping(new DirectoryInfo(Path.Combine(repo, "deploy/compose/keycloak/overlays/cac-piv")), "/overlay")
            .WithPortBinding(8080, assignRandomHostPort: true)
            .WithPortBinding(8443, assignRandomHostPort: true)
            .WithWaitStrategy(Wait.ForUnixContainer().UntilHttpRequestIsSucceeded(r => r.ForPort(8080).ForPath("/realms/keel/.well-known/openid-configuration")))
            .Build();
        await _keycloak.StartAsync();
        Origin = $"https://localhost:{_keycloak.GetMappedPublicPort(8443)}";

        var applied = await ExecAsync("bash", "/overlay/configure-cac-piv.sh", env: new() { ["CAC_FALLBACK"] = Fallback });
        Assert.Equal(0, applied.ExitCode);
        // The two test cardholders: the Keel dev users alice and bob get the EDIPIs on their certificates.
        foreach (var (user, edipi) in new[] { ("alice", "1000000001"), ("bob", "1000000002") })
            Assert.Equal(0, (await ExecAsync("bash", "/overlay/map-credential.sh", user, edipi)).ExitCode);
    }

    internal async Task<(long ExitCode, string Stdout, string Stderr)> ExecAsync(string program, string script, params string[] args) => await ExecAsync(program, script, null, args);

    internal async Task<(long ExitCode, string Stdout, string Stderr)> ExecAsync(string program, string script, Dictionary<string, string>? env, params string[] args)
    {
        var command = new List<string> { "env", "KC_CLI_PASSWORD=" + AdminPassword };
        foreach (var kv in env ?? []) command.Add($"{kv.Key}={kv.Value}");
        command.Add(program); command.Add(script); command.AddRange(args);
        var r = await _keycloak!.ExecAsync(command);
        return (r.ExitCode ?? -1, r.Stdout, r.Stderr);
    }

    /// <summary>Keycloak's log so far: where the reason a certificate was refused is recorded (user_not_found, revoked, ...).</summary>
    internal async Task<string> LogsAsync()
    {
        var (stdout, stderr) = await _keycloak!.GetLogsAsync();
        return stdout + stderr;
    }

    internal IdpBrowser Browser(string? clientCert) =>
        new(Origin, clientCert is null ? null : IdpBrowser.LoadClient(PkiDir, clientCert), Ca);

    // The files are copied into the container as given; the Keycloak user must be able to read them.
    private static void Readable(string path)
    {
        if (!OperatingSystem.IsWindows()) File.SetUnixFileMode(path, UnixFileMode.UserRead | UnixFileMode.GroupRead | UnixFileMode.OtherRead);
    }

    public async ValueTask DisposeAsync()
    {
        GC.SuppressFinalize(this);
        if (_keycloak is not null) await _keycloak.DisposeAsync();
        try { Directory.Delete(_work, true); } catch (IOException) { }
    }

    private static async Task RunAsync(string file, string[] args)
    {
        var psi = new System.Diagnostics.ProcessStartInfo(file) { RedirectStandardOutput = true, RedirectStandardError = true };
        foreach (var a in args) psi.ArgumentList.Add(a);
        using var p = System.Diagnostics.Process.Start(psi)!;
        var err = p.StandardError.ReadToEndAsync();
        await p.WaitForExitAsync();
        Assert.True(p.ExitCode == 0, $"{file} failed: {await err}");
    }

    private static string FindRepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "Keel.slnx"))) dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("Repository root (Keel.slnx) not found.");
    }
}

/// <summary>The recommended policy: certificate only.</summary>
public sealed class KeycloakCertificateOnlyFixture : KeycloakCacFixture { protected override string Fallback => "none"; }

/// <summary>The weaker policy: the stock password form next to the certificate at level 1.</summary>
public sealed class KeycloakPasswordFallbackFixture : KeycloakCacFixture { protected override string Fallback => "password"; }
